{
  "appName": "Event Booking Platform",
  "appType": "event booking",
  "summary": "A platform for organizers to create events and for attendees to reserve tickets, with premium features for organizers.",
  "entities": [
    {
      "name": "event",
      "fields": ["name", "description", "date", "time", "location", "capacity", "organizerId"]
    },
    {
      "name": "ticket",
      "fields": ["eventId", "attendeeId", "type", "price", "quantity"]
    },
    {
      "name": "organizer",
      "fields": ["name", "contactInfo", "planType"]
    },
    {
      "name": "attendee",
      "fields": ["name", "contactInfo"]
    }
  ],
  "roles": ["organizer", "attendee"],
  "features": ["eventCreation", "ticketReservation", "attendeeListManagement", "featuredEventPlacement", "premiumPlan"],
  "hasAuth": true,
  "hasPayments": true,
  "ambiguities": [],
  "assumptions": [
    "Organizers and attendees will have user accounts for authentication.",
    "The 'premium plan' implies a subscription or payment model.",
    "Ticket types might include different prices or access levels.",
    "Attendee lists are specific to each event."
  ],
  "clarifyingQuestions": []
}
